import {
  Card,
  CardContent,
  CardHeader,
  FormControlLabel,
  FormGroup,
  Stack,
  Switch,
  ToggleButton,
  ToggleButtonGroup,
  useTheme,
} from "@mui/material";
import { type ReactNode, useState } from "react";
import { BarChart, PinOutlined, SsidChart } from "@mui/icons-material";
import { Chart, Series, XAxis, YAxis, PlotOptions, Tooltip, Legend } from "../highcharts";
import type { Year, YearMonth } from "./date";
import type { Colour } from "../utils/types";
import type {} from "@mui/material/themeCssVarsAugmentation";
import { convertToCumulative, convertToRanking, groupDate } from "./barchartData";

type GraphType = "bar" | "line" | "bump";

const getSeriesType = (graphType: GraphType, cumulative: boolean): "column" | "spline" | "area" => {
  if (graphType === "bar") return "column";
  if (graphType === "bump") return "spline";
  return cumulative ? "area" : "spline";
};

const Barchart = ({
  title,
  data,
  postAggregate,
  controls,
}: {
  title: string;
  data: (cumulative: boolean) => { name: string; date: YearMonth | Year; colour: Colour; value: number }[];
  /** Converts each aggregated value, e.g. minutes to hours. Empty cells stay empty. */
  postAggregate?: (value: number) => number;
  controls: ReactNode;
}) => {
  const [graphType, setGraphType] = useState<GraphType>("bar");
  const [cumulative, setCumulative] = useState(false);
  const theme = useTheme();

  const effectiveCumulative = cumulative && graphType !== "bar";
  const { results: raw, dates, groups } = groupDate(data(effectiveCumulative));

  const accumulated = effectiveCumulative ? convertToCumulative(raw) : raw;
  // The bump chart plots ranks, but its tooltip still reports the underlying measure.
  const tooltipResults = postAggregate
    ? accumulated.map((row) => row.map((value) => (value == null ? value : postAggregate(value))))
    : accumulated;
  const results = graphType === "bump" ? convertToRanking(tooltipResults) : tooltipResults;

  const seriesType = getSeriesType(graphType, cumulative);

  return (
    <Card>
      <CardHeader
        title={title}
        action={
          <FormGroup>
            {controls}
            <Stack direction={"row"}>
              {graphType !== "bar" && (
                <FormControlLabel
                  label="Cumulative"
                  control={
                    <Switch
                      checked={cumulative}
                      onChange={(_, checked) => setCumulative(checked)}
                    />
                  }
                />
              )}
              <ToggleButtonGroup
                color="primary"
                value={graphType}
                exclusive
                onChange={(_, val: GraphType | null) => val && setGraphType(val)}
              >
                <ToggleButton
                  value={"bump"}
                  sx={{ border: 0 }}
                >
                  <PinOutlined />
                </ToggleButton>
                <ToggleButton
                  value={"line"}
                  sx={{ border: 0 }}
                >
                  <SsidChart />
                </ToggleButton>
                <ToggleButton
                  value={"bar"}
                  sx={{ border: 0 }}
                >
                  <BarChart />
                </ToggleButton>
              </ToggleButtonGroup>
            </Stack>
          </FormGroup>
        }
      />
      <CardContent>
        <Chart
          containerProps={{ style: { height: "80vh" } }}
          options={{
            chart: {
              backgroundColor: "transparent",
              style: {
                color: theme.vars.palette.text.primary,
              },
            },
          }}
        >
          <XAxis
            type="category"
            categories={dates.map((date) => date.toString())}
            labels={{
              style: {
                color: theme.vars.palette.text.primary,
              } as Record<string, string>,
            }}
          />
          <YAxis
            title={{
              text: undefined,
            }}
            reversed={graphType === "bump"}
            floor={graphType === "bump" ? 1 : undefined}
            minTickInterval={1}
            labels={{
              style: {
                color: theme.vars.palette.text.primary,
              } as Record<string, string>,
            }}
            endOnTick={false}
          />
          <PlotOptions
            {...({
              column: {
                stacking: "normal",
                dataLabels: {
                  enabled: false,
                },
                groupPadding: 0,
                events: {
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  click: (event: any) => {
                    const {
                      series: clickedSeries,
                      series: { chart },
                    } = event.point;
                    const hasOtherVisibleSeries = chart.series.some(
                      // eslint-disable-next-line @typescript-eslint/no-explicit-any
                      (series: any) => series !== clickedSeries && series.visible,
                    );
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    chart.series.forEach((series: any) =>
                      series.setVisible(hasOtherVisibleSeries ? series === clickedSeries : true),
                    );
                  },
                },
              },
              area: {
                stacking: "normal",
              },
              spline: {
                tooltip: {
                  pointFormat:
                    '<span style="color:{series.color}">\u25CF</span> {series.name}: <b>{point.tooltip}</b><br/>',
                },
              },
            } as Record<string, unknown>)}
          />
          <Tooltip />
          <Legend
            enabled={groups.length > 1}
            verticalAlign="top"
            align="left"
            itemStyle={{
              color: theme.vars.palette.text.primary,
            }}
          />
          {results.map((values, groupindex) => (
            // @ts-expect-error: TS cannot infer Series component props for union of series types
            <Series
              key={groups[groupindex].name}
              type={seriesType}
              data={values.map((val, valIndex) => ({
                y: val,
                tooltip: tooltipResults[groupindex][valIndex] ?? 0,
              }))}
              options={{
                name: groups[groupindex].name,
                color: groups.length === 1 ? theme.palette.primary.main : groups[groupindex].colour,
                lineWidth: 4,
              }}
            />
          ))}
        </Chart>
      </CardContent>
    </Card>
  );
};

export default Barchart;
